#include "Stabilizer.h"
#include "LoudnessMeter.h"
#include <array>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>
#include <vector>
using Audio=std::array<std::vector<float>,2>;
Audio source(int rate){Audio x;for(auto& c:x)c.resize(rate*5);unsigned seed=23;for(int i=0;i<rate*5;++i){seed=1664525*seed+1013904223;const float noise=(float(seed>>8)/8388608.f-1)*.015f;const double t=double(i)/rate;const float pulse=i%(rate/5)<160?std::exp(-float(i%(rate/5))/42.f)*.55f:0;const float body=.2f*std::sin(6.283185307179586*125*t)+.12f*std::sin(6.283185307179586*700*t)+.08f*std::cos(6.283185307179586*4000*t)+.05f*std::sin(6.283185307179586*12000*t)+noise;x[0][i]=body+pulse;x[1][i]=body*.9f+pulse*.86f-noise*.2f;}return x;}
struct Render {Audio audio;float correction=0;};Render render(const Audio& input,int rate,int intensity,bool tame=true){Render out{input};masterlab::StabilizerSettings settings;settings.enabled=intensity>=0;settings.amount=100;settings.speed=0;settings.smoothing=25;settings.intensity=std::max(0,intensity);settings.tame=tame;masterlab::Stabilizer stabilizer;stabilizer.settings(settings);stabilizer.prepare(rate);for(int offset=0;offset<int(input[0].size());offset+=257){const int n=std::min(257,int(input[0].size())-offset);stabilizer.process(out.audio[0].data()+offset,out.audio[1].data()+offset,n);for(float gain:stabilizer.read())out.correction=std::max(out.correction,std::abs(gain));}return out;}
struct Metrics {double lufs=-120,peak=0,rms=0,crest=0;};Metrics measure(const Audio& audio,int rate){masterlab::LoudnessMeter meter;meter.prepare(rate);Metrics result;double energy=0;size_t count=0;for(size_t i=0;i<audio[0].size();++i){meter.push(audio[0][i],audio[1][i]);if(i>=size_t(rate))for(int channel=0;channel<2;++channel){result.peak=std::max(result.peak,std::abs(double(audio[channel][i])));energy+=double(audio[channel][i])*audio[channel][i];++count;}}result.lufs=meter.read().integrated;result.rms=std::sqrt(energy/count);result.crest=20*std::log10(result.peak/std::max(1e-12,result.rms));return result;}
double delta(const Audio& dry,const Audio& wet,int rate,double gain){double changed=0,reference=0;for(size_t i=rate;i<dry[0].size();++i)for(int channel=0;channel<2;++channel){const double difference=wet[channel][i]*gain-dry[channel][i];changed+=difference*difference;reference+=double(dry[channel][i])*dry[channel][i];}return std::sqrt(changed/reference);}
void wav(const std::filesystem::path& path,const Audio& audio,int rate,double gain){std::ofstream f(path,std::ios::binary);auto u16=[&](unsigned value){f.put(char(value));f.put(char(value>>8));};auto u32=[&](unsigned value){u16(value);u16(value>>16);};const unsigned bytes=unsigned(audio[0].size()*4);f.write("RIFF",4);u32(36+bytes);f.write("WAVEfmt ",8);u32(16);u16(1);u16(2);u32(rate);u32(rate*4);u16(4);u16(16);f.write("data",4);u32(bytes);for(size_t i=0;i<audio[0].size();++i)for(int channel=0;channel<2;++channel)u16(static_cast<unsigned>(static_cast<short>(std::lround(std::clamp(float(audio[channel][i]*gain),-.999f,.999f)*32767))));}
int main(int argc,char** argv){if(argc!=2)return 2;const int rate=48000;const std::filesystem::path directory=argv[1];std::filesystem::create_directories(directory);const auto input=source(rate);Render dry{input},legacy=render(input,rate,0),strong=render(input,rate,2),extreme=render(input,rate,3),extremeUntamed=render(input,rate,3,false);const auto dm=measure(dry.audio,rate),lm=measure(legacy.audio,rate),sm=measure(strong.audio,rate),em=measure(extreme.audio,rate),um=measure(extremeUntamed.audio,rate);std::ostringstream csv;csv<<"render,lufs_raw,peak_raw,crest_db,max_correction_db,match_gain_db,matched_delta_ratio\n";csv<<"dry,"<<dm.lufs<<','<<dm.peak<<','<<dm.crest<<",0,0,0\n";auto row=[&](const char* name,const Render& render,const Metrics& metrics){const double gain=std::pow(10.,(dm.lufs-metrics.lufs)/20);csv<<name<<','<<metrics.lufs<<','<<metrics.peak<<','<<metrics.crest<<','<<render.correction<<','<<20*std::log10(gain)<<','<<delta(dry.audio,render.audio,rate,gain)<<'\n';return gain;};const auto legacyGain=row("legacy",legacy,lm),strongGain=row("strong",strong,sm),extremeGain=row("extreme_tame",extreme,em);row("extreme_untamed",extremeUntamed,um);std::ofstream(directory/"stabilizer-metrics.csv")<<csv.str();wav(directory/"stabilizer-dry.wav",dry.audio,rate,1);wav(directory/"stabilizer-legacy-matched.wav",legacy.audio,rate,legacyGain);wav(directory/"stabilizer-strong-matched.wav",strong.audio,rate,strongGain);wav(directory/"stabilizer-extreme-tame-matched.wav",extreme.audio,rate,extremeGain);std::cout<<csv.str();}
